def get_items():
    all_raw = tdp1.get_objeto() + bdo.generate_objeto_file() + [bc.make_item(*x) for x in RAW_OBJETO_EXTRA]
    return all_raw

def get_new_items():
    existing = bc.get_existing_names_for_theme('Objeto')
    all_cand = get_items()
    
    seen = set()
    unique_new = []
    for x in all_cand:
        name = bc.get_item_name(x)
        norm = bc.normalize_name(name)
        if norm not in existing and norm not in seen:
            seen.add(norm)
            unique_new.append(x)
    return unique_new
